const parsed = $('Spracuj správu').first().json;
const file = $('Stiahni index.html').first().json;

// HTTP Request vrati content ako base64 string
const raw = file.content ?? null;

if (!raw) {
  return [{ json: {
    error: true,
    chatId: parsed.chatId,
    reply: '❌ Súbor sa nepodarilo stiahnuť. Kluce: ' + Object.keys(file).join(', ')
  }}];
}

// Dekoduj base64
const current = Buffer.from(raw.replace(/\n/g, ''), 'base64').toString('utf8');

const newBlock = `var NEW_COURSE = {\n  enabled: true,\n\n  /* Skupina kurzu — zobrazí sa nad nadpisom */\n  type: "${parsed.type}",\n\n  /* Nadpis popupu */\n  title: "${parsed.title}",\n\n  /* Dátum — tučné modré písmo pod nadpisom */\n  date: "${parsed.date}",\n\n  /* Krátky popis */\n  description: "${parsed.description}"\n};`;

const updated = current.replace(/var NEW_COURSE = \{[\s\S]*?\};/, newBlock);

if (updated === current) {
  return [{ json: {
    error: true,
    chatId: parsed.chatId,
    reply: '❌ NEW_COURSE blok sa nenašiel v súbore.'
  }}];
}

return [{ json: {
  error: false,
  chatId: parsed.chatId,
  sha: file.sha,
  updatedContent: updated,
  commitMessage: `Popup: ${parsed.type} — ${parsed.date}`,
  reply: `✅ Popup aktualizovaný!\n\n*${parsed.type}*\n${parsed.date}\n${parsed.description}\n\nVercel redeployuje za ~30 sek.`
}}];

const message = ($input.first().json?.message?.text || '').trim();
const chatId  = $input.first().json?.message?.chat?.id;

const lines = message.split('\n').map(l => l.trim()).filter(l => l);

if (lines.length < 2) {
  return [{ json: {
    error: true,
    chatId,
    reply: '❌ Nesprávny formát. Pošli:\nSkupina B\n15. jún 2026\nPopis kurzu'
  }}];
}

return [{ json: {
  error: false,
  chatId,
  type: lines[0],
  date: lines[1],
  description: lines[2] || '',
  title: `Otvárame nový kurz ${lines[0].toLowerCase()}`
}}];
